# Search for puzzle-related files using Python
import os
import json
from pathlib import Path

base_path = Path("/home/USER/runs/paper/qwen-h0-card")

def find_files(directory, max_results=100):
    found = []
    for ext in ['*.json', '*.txt']:
        for f in directory.rglob(ext):
            # Check if file has relevant content
            try:
                if '2b4524cc' in f.name or ('7' in f.name and 'input' in f.name.lower()):
                    found.append(f)
                elif f.stat().st_size < 10000:  # Small files are more likely to be task data
                    try:
                        with open(f, 'r') as fp:
                            preview = fp.read(100)
                            if '[' in preview or '{' in preview:  # JSON-like
                                found.append((f, fp))
                    except:
                        pass
            except:
                pass
    return found[:max_results]

print("Searching for puzzle files...")
files = find_files(base_path)
for f in files:
